function [a] = tb_accel(s, b, gm, model, nmax)
%TB_ACCEL  thirdbody.accel(rSat, rBody, GM, model, nmax): the model's acceleration (nmax for the Legendre series).
%   The direct model's cancellation amplifies pow's last bit: a translation is held to 1e-8 of the largest output.
%   tolerance: 1e-8
%   s: real[1][3] (passed a plain number)
%   b: real[1][3] (passed a plain number)
%   gm: real[1] (passed a plain number)
%   model: ThirdBodyModel (passed a choice, as its option's number)
%   nmax: int (passed a whole number)
%   returns a: real[1][3] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(3, 1);
    if (model == 0)
        a = asils.models.thirdbody.tb_battin(s, b, gm);
    elseif (model == 1)
        a = asils.models.thirdbody.tb_direct(s, b, gm);
    elseif (model == 2)
        a = asils.models.thirdbody.tb_tidal(s, b, gm);
    else
        a = asils.models.thirdbody.tb_legendre(s, b, gm, nmax);
    end
end
